package main

import (
	"fmt"
	"sort"
)

func special(u, k int, a []int) int {
	if a[u] == 1 {
		return k - u
	}
	if a[k] == 1000 {
		return k - u
	}
	return k - u - 1
}

func main() {
	var n int
	fmt.Scan(&n)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&a[i])
	}
	sort.Ints(a)

	maxVal := 0
	u := 0
	k := 0
	g := true

	for i := 0; i < n-1; i++ {
		if a[i+1]-a[i] == 1 && g {
			u = i
			g = false
		}
		if a[i+1]-a[i] != 1 && !g {
			k = i
			g = true
			l := special(u, k, a)
			if l > maxVal {
				maxVal = l
			}
		}
	}

	if !g {
		k = n - 1
		l := special(u, k, a)
		if l > maxVal {
			maxVal = l
		}
	}

	fmt.Println(maxVal)
}

